python3 - <<'EOF'
import os, re
root='/challenge/inhere'
for dirpath,_,files in os.walk(root):
    for fn in sorted(files):
        p=os.path.join(dirpath,fn)
        data=open(p,'rb').read()
        area=re.search(r'area(\d+)',p).group(1)
        item=fn[4:]
        if set(data)=={0}: 
            continue
        if set(data)=={ord('x')}:
            continue
        expected=(f"record {area}-{item}\n".encode())* (len(data)//13+1)
        expected=expected[:len(data)]
        if data!=expected:
            print("ANOMALY:",p,len(data))
            # show first difference
            for i,(a,b) in enumerate(zip(data,expected)):
                if a!=b:
                    print(" first diff at",i, data[max(0,i-20):i+60])
                    break
